import 'server-only'
import { readFile } from 'node:fs/promises'
import path from 'node:path'

/**
 * Reads CHANGELOG.md, or returns null when the build has none (the page shows a translated
 * notice). The file is generated by git-cliff, so it is only ever read, never written.
 * In development the process runs in `apps/web`, so the file is two levels up; in the production
 * image the Dockerfile copies it next to `apps/web/server.js` (the working directory).
 */
export async function readChangelog(): Promise<string | null> {
  const candidates = [
    path.join(process.cwd(), '../../CHANGELOG.md'),
    path.join(process.cwd(), 'CHANGELOG.md'),
  ]
  for (const file of candidates) {
    try {
      return await readFile(/* turbopackIgnore: true */ file, 'utf8')
    } catch {
      // Try the next location.
    }
  }
  return null
}
